#!/bin/bash
#
# Opens a PR on nickjlamb/nickjlamb that updates the profile README.
# Uses your authenticated gh CLI - no local clone, no git writes on disk.
# Run:  bash open-profile-pr.sh
#
set -eo pipefail

REPO="nickjlamb/nickjlamb"
BRANCH="profile-ecosystem-refresh"
FILE="README.md"
TITLE="Refresh profile: OpenGATE-anchored open-source ecosystem"

if ! command -v gh >/dev/null 2>&1; then
  echo "ERROR: GitHub CLI (gh) not found. Install it: https://cli.github.com" >&2; exit 1
fi
if ! gh auth status >/dev/null 2>&1; then
  echo "ERROR: gh is not authenticated. Run: gh auth login" >&2; exit 1
fi

CONTENT_B64=$(cat <<'B64EOF'

B64EOF
)

echo "-> Reading current main + file SHAs..."
BASE_SHA=$(gh api "repos/${REPO}/git/ref/heads/main" --jq .object.sha)
FILE_SHA=$(gh api "repos/${REPO}/contents/${FILE}?ref=main" --jq .sha)

echo "-> Creating branch ${BRANCH} ..."
gh api "repos/${REPO}/git/refs" -f ref="refs/heads/${BRANCH}" -f sha="${BASE_SHA}" \
  >/dev/null 2>&1 || echo "   (branch already exists - reusing it)"

echo "-> Committing new README to ${BRANCH} ..."
gh api "repos/${REPO}/contents/${FILE}" -X PUT \
  -f message="Profile: rebuild Open Source section around the OpenGATE-verified ecosystem" \
  -f content="${CONTENT_B64}" \
  -f sha="${FILE_SHA}" \
  -f branch="${BRANCH}" \
  --jq '.commit.html_url' | sed 's/^/   commit: /'

echo "-> Opening pull request..."
gh pr create --repo "${REPO}" --base main --head "${BRANCH}" \
  --title "${TITLE}" \
  --body "Rebuilds the Open Source section of the profile around the verified ecosystem; everything above it is unchanged. Adds OpenGATE (verification spine) with the PubCrawl regression proof point, an ecosystem table with live npm download badges, refreshed PubCrawl (Europe PMC, 14 tools, OpenGATE release gate), and new Redacta and StudyDiff entries. RSI Loop and LitRAG kept below as concept implementations. All numbers are live shields.io badges." \
  2>/dev/null && echo "DONE: PR opened - the URL is printed above." \
  || gh pr view --repo "${REPO}" "${BRANCH}" --json url --jq '"DONE: PR already exists: " + .url'
